import {uiQuery} from './router.js';
import {progressCounts,taskPriority,uploadState,upcomingMilestones} from './progress-core.js';
import {attendanceSignal,safeResourceUrl} from './course-core.js';
const $=s=>uiQuery(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=value=>value?new Intl.DateTimeFormat('tr-TR',{timeZone:'Europe/Istanbul',day:'numeric',month:'short',...(value.includes('T')?{hour:'2-digit',minute:'2-digit'}:{})}).format(new Date(value.length===10?value+'T12:00:00+03:00':value)):'Bilinmiyor';
const labels={full:'Kendi dosya sayısı tam',partial:'Kısmi yükleme',none:'Kendi yüklemesi görünmüyor',group_unknown:'Grup / kapsam belirsiz',unknown:'Sayısı bilinmiyor'};
let snapshot=null,data,getCompleted,attendance=window.keplerAttendanceOverview||{items:[],state:'loading'},loadFailed=false;
const link=(url,label)=>{const safe=safeResourceUrl(url,location.origin);return safe?`<a href="${esc(safe)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:'';};
function render(){
 const root=$('#progressOverview');if(!root)return;const now=new Date(),records=snapshot?.records||[],counts=progressCounts(records),outdated=!snapshot?.checkedAt||(now-new Date(snapshot.checkedAt))/36e5>data.staleAfterHours;
 const tasks=data.tasks.filter(t=>!getCompleted()[t.id]).map(task=>({task,...taskPriority(task,now,data.staleAfterHours)})).filter(item=>item.rank>=3).sort((a,b)=>b.rank-a.rank||(a.task.dueAt||a.task.date).localeCompare(b.task.dueAt||b.task.date)).slice(0,3);
 const critical=data.courses.map(c=>({course:c,signal:attendanceSignal(attendance.items.find(i=>i.courseId===c.id),attendance.state)})).filter(x=>x.signal.tone==='critical');
 root.innerHTML=`<div class="home-summary">${snapshot?`<div class="summary-stat"><span class="summary-stat-icon" aria-hidden="true">▤</span><div><strong>${counts.total}</strong><span>Kayıtlı ödev</span></div></div><div class="summary-stat"><span class="summary-stat-icon success" aria-hidden="true">✓</span><div><strong>${counts.ownComplete}<small> / ${counts.total}</small></strong><span>Kendi dosya sayısı tam</span></div></div><a class="summary-stat" href="#/tasks"><span class="summary-stat-icon warm" aria-hidden="true">◷</span><div><strong>${upcomingMilestones(data,now,14).length}</strong><span>14 günde ders hedefi →</span></div></a>`:`<p role="status">${loadFailed?'Ödev sayımları yüklenemedi.':'Kayıt özeti hazırlanıyor…'}</p>`}</div><section id="courseTracking" aria-labelledby="trackingTitle"></section>${critical.length?`<div class="home-warning"><span class="signal-icon" aria-hidden="true">!</span><div><strong>${critical.map(x=>esc(x.course.id)).join(', ')} · kişisel yoklama limitine dikkat</strong><span>Yalnızca kendi kayıt ve limitlerin; resmî yoklama sonucu değil.</span></div><a href="#/attendance" data-open-panel="attendance" data-attendance-course="${esc(critical[0].course.id)}">Kayıtları gör →</a></div>`:''}<div class="home-next-heading"><div><p class="workspace-kicker">BİR SONRAKİ ADIM</p><h2 id="progressTitle">Önce bunlara odaklan.</h2></div><a href="#/tasks">Tüm işler →</a></div><div class="home-next-list">${tasks.length?tasks.map(({task:t,tone,label})=>`<a class="home-next-item priority-${tone}" href="#/courses/${encodeURIComponent(t.courseId)}/assignments"><span class="home-task-symbol" aria-hidden="true">${tone==='red'?'!':t.kind==='milestone'?'◇':'▤'}</span><div><span class="home-task-course">${esc(t.courseId)} · ${esc(label)}</span><h3>${esc(t.title)}</h3><span class="home-task-date">${esc(date(t.dueAt||t.date))}${t.dueAt?' · İstanbul':' · Saat belirtilmedi'}</span></div><span class="home-next-arrow" aria-hidden="true">↗</span></a>`).join(''):'<div class="home-clear-state"><span aria-hidden="true">✦</span><p>Bu veri kopyasında yakın tarihli hazırlık görünmüyor.</p><a href="#/tasks">İşlerini ve kontrol durumunu aç →</a></div>'}</div>${snapshot?`<details class="home-evidence"><summary>Bu özet neye dayanıyor? ${outdated?'· Kontrol eski':''}</summary><p>Liste kontrolü: ${esc(date(snapshot.checkedAt))} İstanbul. ${esc(snapshot.scope)} Dosya adedi değil, ödev adedi: 3/3 dosya tek ödevdir. Kendi dosya sayısı tam olması kabul, not veya zamanında teslim kanıtı değildir. Grup/kapsam belirsiz kayıtlar kendi tam sayımına dahil olabilir.</p><div class="progress-categories">${Object.entries(labels).map(([key,label])=>`<span>${esc(label)}: <b>${counts[key]}</b></span>`).join('')}</div><details><summary>${counts.total} ödev kaydını göster</summary><div class="progress-records">${records.map(r=>{const state=uploadState(r);return `<article><span>${esc(r.courseId)}</span><div><h3>${esc(r.title)}</h3><p>${esc(state.label)} · ${r.ownUploaded}/${r.expectedFiles} dosya</p><small>Kontrol: ${esc(date(r.verifiedAt))} İstanbul</small></div>${link(r.sourceUrl,'Sayım kaynağı')}</article>`}).join('')}</div></details></details>`:''}`;
 document.dispatchEvent(new CustomEvent('kepler:progress-rendered'));
}
export function initProgress(value,completed){data=value;getCompleted=completed;attendance=window.keplerAttendanceOverview||attendance;render();fetch('assignment-inventory.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Inventory unavailable');return r.json()}).then(value=>{snapshot=value;window.keplerAssignmentSnapshot=value;document.dispatchEvent(new CustomEvent('kepler:assignment-snapshot',{detail:{snapshot:value,state:'ready'}}));render()}).catch(()=>{loadFailed=true;document.dispatchEvent(new CustomEvent('kepler:assignment-snapshot',{detail:{state:'unavailable'}}));render()});document.addEventListener('kepler:attendance-overview',e=>{attendance=e.detail;render()});document.addEventListener('kepler:plan-changed',render);}
